tree.content:
// The append-only journal and the per-destination read offsets.
//
// The journal is the hub's audit trail.  It holds the CONTENT, so it is a
// local file, and it is readable only by the user: the state directory is
// created with mode 700 and every file in it with mode 600.
//
// One JSON object per line, fsynced on write.  A crash can lose the tail of
// the file, never reorder it and never interleave two lines.
//
// Each destination (the UM turn channel, the UM ledger channel and Sentry)
// keeps its OWN read offset and its OWN set of already-sent event ids, in
// separate small state files.  A destination that is down therefore never
// holds the other one back.
//
// The offset advances ONLY after a successful delivery.  A crash between
// "delivered" and "offset advanced" would resend, so every sender also
// checks the sent set before it sends.  Sentry does not dedupe OTLP logs,
// which is why that check is not optional.
//
// The offset is an ABSOLUTE byte position in the logical journal stream.
// The file on disk only holds the part of the stream that is not consumed
// yet: once the file grows past MAX_JOURNAL_BYTES, the prefix that every
// destination has already read is dropped and the base of the file moves
// forward.  The offsets themselves never change, so a compaction can
// neither lose nor replay an event.  The prefix that is dropped is a whole
// number of lines, because every offset sits on a line boundary.
//
// Every persisted state file and every journal row is validated with Zod
// before it is used.  A malformed state file is rejected instead of being
// half believed, and a malformed row is dropped instead of reaching a
// sender with an invalid identity.
//
// Zod is a runtime dependency of this repository.  The hub therefore has one
// third-party import, and it is on the parsing boundary, where an explicit
// runtime shape guard belongs.

import { constants as fsConstants } from "node:fs";
import { createHash, randomUUID } from "node:crypto";
import { chmod, link, mkdir, open, readFile, rename, stat, unlink, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { StringDecoder } from "node:string_decoder";
import { z } from "zod";

import { NULL_LOGGER } from "./internal-event.mjs";
import { rebuildLogBody, scalarFromAnyValue, scrubOtlpAttributes } from "./allowlist.mjs";

const DIR_MODE = 0o700;
const FILE_MODE = 0o600;

/** How many already-sent event ids one destination remembers. */
export const MAX_SENT_IDS = 10_000;

/** The journal file is compacted once it grows past this size. */
export const MAX_JOURNAL_BYTES = 32 * 1024 * 1024;

/** Read chunk size when scanning the journal. */
const READ_CHUNK_BYTES = 256 * 1024;

/** The file that records where the journal file starts in the stream. */
const BASE_FILE = "journal.base.json";
const SENTRY_REQUEST_FILE = "sentry-request.json";
export const MAX_SENTRY_REQUEST_BYTES = 2 * 1024 * 1024;
const SentryResponseClass = z.enum(["partial_success", "malformed_ack", "oversized_ack", "unreadable_ack", "unexpected_content_type"]);
const SentryWireEventSchema = z.strictObject({
  eventId: z.string().min(1).max(256), ts: z.string().max(64), kind: z.enum(["span", "log"]),
  name: z.string().max(160), attributes: z.array(z.unknown()).max(64),
  durationMs: z.number().finite().nonnegative().max(Number.MAX_SAFE_INTEGER).optional(),
  body: z.strictObject({ stringValue: z.string() }).optional(),
  severityNumber: z.union([z.literal(9), z.literal(17)]).optional(),
  status: z.strictObject({ code: z.union([z.literal(1), z.literal(2)]) }).optional(),
});
const SentryRequestSchema = z.strictObject({
  version: z.literal(1), destination: z.literal("sentry"), signal: z.enum(["logs", "traces"]),
  batchDigest: z.string().regex(/^[a-f0-9]{64}$/), phase: z.enum(["prepared", "held"]),
  eventIds: z.array(z.string().min(1).max(256)).min(1).max(1000),
  events: z.array(SentryWireEventSchema).min(1).max(1000),
  responseClass: SentryResponseClass.optional(), rejectedCount: z.number().int().nonnegative().max(1000).optional(),
  httpStatus: z.number().int().min(200).max(299).optional(),
});

function sentryRequestEvents(events, signal) {
  if (!Array.isArray(events) || !events.length || events.length > (signal === "logs" ? 100 : 1000)) throw new Error("Invalid Sentry request size");
  return events.map((event) => {
    const eventId = eventIdOf(event);
    if (!eventId || !Number.isFinite(Date.parse(event.ts))) throw new Error("Invalid Sentry request identity");
    const attributes = scrubOtlpAttributes(event.attributes);
    const operation = attributes.find((a) => a.key === "gen_ai.operation.name");
    const name = operation ? scalarFromAnyValue(operation.value) : signal === "logs" ? "log" : "chat";
    const safe = { eventId, ts: event.ts, kind: signal === "logs" ? "log" : "span", name: typeof name === "string" ? name.slice(0, 160) : "chat", attributes };
    if (Number.isFinite(event.durationMs) && event.durationMs >= 0 && event.durationMs <= Number.MAX_SAFE_INTEGER) safe.durationMs = event.durationMs;
    if (signal === "logs") {
      safe.body = { stringValue: rebuildLogBody(attributes) };
      safe.severityNumber = event.severityNumber === 17 ? 17 : 9;
    } else safe.status = { code: event.status?.code === 2 ? 2 : 1 };
    return SentryWireEventSchema.parse(safe);
  });
}

function sentryBatchDigest(signal, events) {
  return createHash("sha256").update(JSON.stringify({ signal, events })).digest("hex");
}

/** The persisted read offset of one destination. */
const OffsetStateSchema = z.object({
  offset: z.number().int().nonnegative(),
});

/** The persisted set of delivered event ids of one destination. */
const SentStateSchema = z.object({
  eventIds: z.array(z.string().min(1).max(256)).max(MAX_SENT_IDS),
});

/**
 * One journal row.
 *
 * The identity fields are required: a row without an event id cannot be
 * deduplicated and a row without a timestamp cannot be ordered.  The rest
 * of the row is the internal event, which is passed through as it is.
 */
const JournalEventSchema = z.looseObject({
  eventId: z.string().min(1).max(256),
  ts: z.string().min(1).max(64),
  kind: z.enum(["span", "log"]).optional(),
  platform: z.string().max(200).optional(),
});

/** The compaction bookkeeping of the journal file. */
const BaseStateSchema = z.object({
  base: z.number().int().nonnegative(),
  nextBase: z.number().int().nonnegative(),
  pendingSize: z.number().int().nonnegative(),
});

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

/**
 * A tiny promise mutex.
 *
 * Two places must not interleave: the appends and the compaction of the
 * journal file, and the writes of the per-destination state files.  Each
 * one gets its own mutex.
 */
function createMutex() {
  let tail = Promise.resolve();
  return function run(task) {
    const result = tail.then(task, task);
    tail = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  };
}

/**
 * The id of an event, when the event carries a valid one.
 *
 * The journal validates every row before a sender can see it, so this is
 * the second guard for a caller that maps ids out of an event.
 */
export function eventIdOf(event) {
  const checked = JournalEventSchema.safeParse(event);
  return checked.success ? checked.data.eventId : undefined;
}

/** A destination name becomes a file name, so it is restricted. */
export function normalizeDestination(name) {
  const value = String(name ?? "").trim().toLowerCase();
  if (!/^[a-z0-9][a-z0-9_-]{0,39}$/.test(value)) {
    throw new Error(`Invalid destination name: ${String(name).slice(0, 40)}`);
  }
  return value;
}

export class Journal {
  /**
   * @param {object} options
   * @param {string} options.dir       State directory.  Created with mode 700.
   * @param {object} [options.logger]
   * @param {number} [options.maxJournalBytes]  The size the journal file
   *        passes before the consumed prefix is dropped.
   */
  constructor({ dir, logger = NULL_LOGGER, maxJournalBytes = MAX_JOURNAL_BYTES } = {}) {
    if (typeof dir !== "string" || !dir.trim()) throw new Error("Journal dir is required");
    this.dir = dir;
    this.logger = logger;
    this.maxJournalBytes = Number.isSafeInteger(maxJournalBytes) && maxJournalBytes > 0
      ? maxJournalBytes
      : MAX_JOURNAL_BYTES;
    this.journalPath = join(dir, "journal.jsonl");
    this.stateDir = join(dir, "state");
    this.deadLetterPath = join(dir, "dead-letter.jsonl");
    this.handle = undefined;
    this.offsets = new Map();
    this.sentSets = new Map();
    //  The absolute byte position of the first retained byte of the file.
    this.base = 0;
    this.fileMutex = createMutex();
    this.stateMutex = createMutex();
    this.writeCounter = 0;
  }

  /** Create the directory tree with tight modes and open the journal. */
  async open() {
    await mkdir(this.stateDir, { recursive: true, mode: DIR_MODE });
    await chmod(this.dir, DIR_MODE);
    await chmod(this.stateDir, DIR_MODE);
    await this.recoverBase();
    this.handle = await open(this.journalPath, "a", FILE_MODE);
    await this.handle.chmod(FILE_MODE);
    return this;
  }

  /**
   * Read the compaction bookkeeping and settle an interrupted compaction.
   *
   * The base file records the base of the file, the base the file WILL have
   * after a compaction, and the size the file had before that compaction.
   * A compaction interrupted after the swap left a file that is smaller
   * than the recorded size, so the new base is the right one.  A compaction
   * interrupted before the swap left the file untouched, so the old base is
   * the right one.
   */
  async recoverBase() {
    const state = await this.readBaseFile();
    let base = 0;
    if (state) {
      if (state.pendingSize > 0) {
        const size = await this.fileSize();
        base = size < state.pendingSize ? state.nextBase : state.base;
      } else {
        base = state.base;
      }
    }
    this.base = base;
    await this.writeBaseFile({ base, nextBase: base, pendingSize: 0 });
    return base;
  }

  async readBaseFile() {
    try {
      const raw = await readFile(join(this.stateDir, BASE_FILE), "utf8");
      const parsed = BaseStateSchema.safeParse(JSON.parse(raw));
      if (!parsed.success) {
        this.logger.warn("the journal base state is not usable", { file: BASE_FILE });
        return null;
      }
      return parsed.data;
    } catch {
      return null;
    }
  }

  async writeBaseFile(state) {
    await this.writeStateFile(BASE_FILE, state);
  }

  /** Load the persisted offsets and sent sets for the known destinations. */
  async loadDestinations(destinations) {
    for (const raw of destinations) {
      const destination = normalizeDestination(raw);
      if (this.offsets.has(destination)) continue;
      this.offsets.set(destination, await this.readOffsetFile(destination));
      this.sentSets.set(destination, await this.readSentFile(destination));
    }
  }

  async readOffsetFile(destination) {
    try {
      const raw = await readFile(join(this.stateDir, `${destination}.offset.json`), "utf8");
      const parsed = OffsetStateSchema.safeParse(JSON.parse(raw));
      if (!parsed.success) {
        this.logger.warn("the offset state is not usable", { destination });
        return 0;
      }
      return parsed.data.offset;
    } catch {
      return 0;
    }
  }

  async readSentFile(destination) {
    try {
      const raw = await readFile(join(this.stateDir, `${destination}.sent.json`), "utf8");
      const parsed = SentStateSchema.safeParse(JSON.parse(raw));
      if (!parsed.success) {
        this.logger.warn("the sent state is not usable", { destination });
        return new Set();
      }
      return new Set(parsed.data.eventIds);
    } catch {
      return new Set();
    }
  }

  /**
   * Append one internal event and fsync it.
   *
   * The line is serialized with JSON.stringify, so a newline inside a value
   * can never split the record across two lines.
   */
  async append(event) {
    return this.appendBatch([event]);
  }

  /**
   * Append a batch of internal events with ONE write and ONE fsync.
   *
   * A receiver request can carry a hundred events.  Flushing once per event
   * turns one request into a hundred disk flushes and delays the response,
   * which invites the producer to retry and duplicate the spans.
   */
  async appendBatch(events) {
    const list = Array.isArray(events) ? events : [];
    if (list.length === 0) return 0;
    for (const event of list) {
      if (!isPlainObject(event)) throw new Error("Journal append needs an object");
    }
    const body = `${list.map((event) => JSON.stringify(event)).join("\n")}\n`;
    const bytes = Buffer.byteLength(body, "utf8");
    await this.fileMutex(async () => {
      if (!this.handle) throw new Error("Journal is not open");
      await this.handle.write(body, null, "utf8");
      await this.handle.sync();
    });
    await this.maybeCompact();
    return bytes;
  }

  /** The current read offset of one destination. */
  getOffset(destination) {
    const key = normalizeDestination(destination);
    return this.offsets.get(key) ?? 0;
  }

  /** Persist the read offset of one destination. */
  async setOffset(destination, offset) {
    const key = normalizeDestination(destination);
    if (!Number.isSafeInteger(offset) || offset < 0) throw new Error("Offset must be a non-negative integer");
    await this.stateMutex(async () => {
      await this.writeStateFile(`${key}.offset.json`, { offset });
      this.offsets.set(key, offset);
    });
    await this.maybeCompact();
  }

  /** True when this destination already delivered the event. */
  isSent(destination, eventId) {
    const key = normalizeDestination(destination);
    if (typeof eventId !== "string" || !eventId) return false;
    return (this.sentSets.get(key) ?? new Set()).has(eventId);
  }

  /** Record that this destination delivered the event. */
  async markSent(destination, eventId) {
    const key = normalizeDestination(destination);
    if (typeof eventId !== "string" || !eventId) return;
    await this.stateMutex(async () => {
      const set = new Set(this.sentSet(key));
      if (set.has(eventId)) return;
      set.add(eventId);
      this.trimSentSet(set);
      await this.writeStateFile(`${key}.sent.json`, { eventIds: [...set] });
      this.sentSets.set(key, set);
    });
  }

  /** Record a batch of delivered event ids. */
  async markSentBatch(destination, eventIds) {
    const key = normalizeDestination(destination);
    await this.stateMutex(async () => {
      const set = new Set(this.sentSet(key));
      let changed = false;
      for (const eventId of eventIds) {
        if (typeof eventId !== "string" || !eventId || set.has(eventId)) continue;
        set.add(eventId);
        changed = true;
      }
      this.trimSentSet(set);
      if (changed) {
        await this.writeStateFile(`${key}.sent.json`, { eventIds: [...set] });
        this.sentSets.set(key, set);
      }
    });
  }

  sentSet(key) {
    let set = this.sentSets.get(key);
    if (!set) {
      set = new Set();
      this.sentSets.set(key, set);
    }
    return set;
  }

  trimSentSet(set) {
    while (set.size > MAX_SENT_IDS) {
      const oldest = set.values().next().value;
      set.delete(oldest);
    }
  }

  /**
   * Write one state file.
   *
   * The temporary path is unique per write, so two concurrent writes can
   * never truncate the same temporary file, and the rename that publishes
   * the file is atomic.
   */
  async writeStateFile(fileName, payload, { exclusive = false } = {}) {
    const target = join(this.stateDir, fileName);
    const temporary = this.tempPath(target);
    const body = `${JSON.stringify(payload)}\n`;
    try {
      const file = await open(temporary, "wx", FILE_MODE);
      try {
        await file.writeFile(body);
        await this.syncStateFile(file);
      } finally { await file.close(); }
      if (exclusive) await link(temporary, target);
      else await rename(temporary, target);
      await chmod(target, FILE_MODE);
      await this.syncStateDirectory();
    } finally { await unlink(temporary).catch((error) => { if (error.code !== "ENOENT") throw error; }); }
  }

  async syncStateFile(file) { await file.sync(); }

  async syncStateDirectory() {
    const directory = await open(this.stateDir, "r");
    try { await directory.sync(); } finally { await directory.close(); }
  }

  /** An unresolved pre-POST intent is a channel hold, including after a restart. */
  async readSentryRequest() {
    let file;
    try { file = await open(join(this.stateDir, SENTRY_REQUEST_FILE), fsConstants.O_RDONLY | fsConstants.O_NOFOLLOW); }
    catch (error) { if (error.code === "ENOENT") return null; throw error; }
    let bytes;
    try {
      const info = await file.stat();
      if (!info.isFile() || info.size > MAX_SENTRY_REQUEST_BYTES) throw new Error("Invalid Sentry request state");
      bytes = await file.readFile("utf8");
    } finally { await file.close(); }
    const request = SentryRequestSchema.parse(JSON.parse(bytes));
    const events = sentryRequestEvents(request.events, request.signal);
    if (JSON.stringify(events) !== JSON.stringify(request.events) || sentryBatchDigest(request.signal, events) !== request.batchDigest || JSON.stringify(events.map((e) => e.eventId)) !== JSON.stringify(request.eventIds) || new Set(request.eventIds).size !== events.length || (request.rejectedCount ?? 0) > events.length) throw new Error("Invalid Sentry request state");
    return request;
  }

  async prepareSentryRequest(signal, events) {
    if (!["logs", "traces"].includes(signal)) throw new Error("Invalid Sentry signal");
    return this.stateMutex(async () => {
      if (await this.readSentryRequest()) throw new Error("Unresolved Sentry request retained");
      const safe = sentryRequestEvents(events, signal);
      const request = SentryRequestSchema.parse({ version: 1, destination: "sentry", signal, phase: "prepared", batchDigest: sentryBatchDigest(signal, safe), events: safe, eventIds: safe.map((e) => e.eventId) });
      if (new Set(request.eventIds).size !== safe.length || Buffer.byteLength(JSON.stringify(request)) > MAX_SENTRY_REQUEST_BYTES) throw new Error("Invalid Sentry request bounds");
      await this.writeStateFile(SENTRY_REQUEST_FILE, request, { exclusive: true });
      return request;
    });
  }

  async holdSentryRequest(batchDigest, { responseClass, rejectedCount, httpStatus }) {
    return this.stateMutex(async () => {
      const request = await this.readSentryRequest();
      if (!request || request.batchDigest !== batchDigest) throw new Error("Sentry request identity changed");
      const held = SentryRequestSchema.parse({ ...request, phase: "held", responseClass, httpStatus, ...(rejectedCount === undefined ? {} : { rejectedCount }) });
      if ((rejectedCount ?? 0) > request.events.length || Buffer.byteLength(JSON.stringify(held)) > MAX_SENTRY_REQUEST_BYTES) throw new Error("Invalid Sentry hold bounds");
      await this.writeStateFile(SENTRY_REQUEST_FILE, held);
      return held;
    });
  }

  async clearSentryRequest(batchDigest) {
    return this.stateMutex(async () => {
      const request = await this.readSentryRequest();
      if (!request || request.phase !== "prepared" || request.batchDigest !== batchDigest) throw new Error("Unresolved Sentry request preserved");
      await unlink(join(this.stateDir, SENTRY_REQUEST_FILE));
      await this.syncStateDirectory();
    });
  }

  /** A temporary path that no other write can collide with. */
  tempPath(target) {
    this.writeCounter += 1;
    return `${target}.${process.pid}.${this.writeCounter}.${randomUUID()}.tmp`;
  }

  /**
   * Read up to `limit` events for one destination, starting at its offset.
   *
   * Events this destination already sent are skipped, and the returned
   * `endOffset` points past every line that was consumed, so a skipped
   * event never blocks the ones behind it.  A repeated event id inside one
   * batch is skipped as well, so one turn is never delivered twice.
   *
   * A partial trailing line (a crash mid-write) is never parsed and never
   * counted, so the offset stays on a line boundary.
   *
   * A row that does not match the journal schema is dropped: it cannot be
   * deduplicated and it must not reach a sender.
   */
  async readBatch(destination, limit) {
    const key = normalizeDestination(destination);
    const start = this.getOffset(key);
    const sent = this.sentSets.get(key) ?? new Set();
    const events = [];
    if (!this.handle && !(await this.exists())) {
      return { events, endOffset: start };
    }
    //  The base and the file are taken together, under the file mutex, so
    //  a compaction cannot slip between them.  A compaction that runs
    //  after this point replaces the file, but the handle below still
    //  points at the file this read belongs to, so the positions of this
    //  read and the base of this read always belong together.
    const opened = await this.fileMutex(async () => {
      const base = this.base;
      const file = await open(this.journalPath, fsConstants.O_RDONLY);
      let size;
      try {
        size = (await file.stat()).size;
      } catch (error) {
        //  The handle is only closed by the `finally` below once it has
        //  been handed out, so a failure here has to close it itself.
        //  Otherwise every read that fails after the open leaks a
        //  descriptor until the process runs out of them.
        await file.close();
        throw error;
      }
      return { base, file, size };
    });
    const { base, file, size } = opened;
    try {
      const fileStart = Math.max(0, start - base);
      if (fileStart >= size) return { events, endOffset: start };
      const decoder = new StringDecoder("utf8");
      const buffer = Buffer.alloc(READ_CHUNK_BYTES);
      const seen = new Set();
      let pending = "";
      let pendingStart = fileStart;
      let filePos = fileStart;
      let endOffset = start;
      let done = false;
      while (!done && events.length < limit) {
        const remaining = size - filePos;
        if (remaining <= 0) break;
        const want = Math.min(READ_CHUNK_BYTES, remaining);
        const { bytesRead } = await file.read(buffer, 0, want, filePos);
        if (bytesRead <= 0) break;
        filePos += bytesRead;
        pending += decoder.write(buffer.subarray(0, bytesRead));
        for (;;) {
          const newline = pending.indexOf("\n");
          if (newline === -1) break;
          const line = pending.slice(0, newline);
          const consumed = Buffer.byteLength(line, "utf8") + 1;
          pending = pending.slice(newline + 1);
          pendingStart += consumed;
          endOffset = base + pendingStart;
          const trimmed = line.trim();
          if (!trimmed) continue;
          let parsed = null;
          try {
            parsed = JSON.parse(trimmed);
          } catch {
            parsed = null;
          }
          const checked = JournalEventSchema.safeParse(parsed);
          if (!checked.success) continue;
          const event = checked.data;
          if (sent.has(event.eventId)) continue;
          if (seen.has(event.eventId)) continue;
          seen.add(event.eventId);
          events.push(event);
          if (events.length >= limit) break;
        }
      }
      return { events, endOffset };
    } finally {
      await file.close();
    }
  }

  async exists() {
    try {
      await stat(this.journalPath);
      return true;
    } catch {
      return false;
    }
  }

  /** The size of the journal file on disk. */
  async fileSize() {
    try {
      const info = await stat(this.journalPath);
      return info.size;
    } catch {
      return 0;
    }
  }

  /** The smallest offset of every known destination. */
  minimumOffset() {
    if (this.offsets.size === 0) return undefined;
    let min = Infinity;
    for (const offset of this.offsets.values()) {
      if (offset < min) min = offset;
    }
    return Number.isFinite(min) ? min : undefined;
  }

  /**
   * Drop the part of the journal every destination has already read.
   *
   * The offsets are absolute, so removing a prefix does not change them:
   * only the base of the file moves.  The region that is removed is the
   * part below the smallest offset, so no destination can lose an event it
   * has not read yet.  A destination that is down keeps the journal from
   * shrinking, which is the price of not dropping its events.
   */
  async maybeCompact() {
    const target = this.minimumOffset();
    if (target === undefined) return false;
    if (target <= this.base) return false;
    const size = await this.fileSize();
    if (size <= this.maxJournalBytes) return false;
    //  The compaction rewrites the whole remaining file, so it is only
    //  worth its copy when the consumed prefix is a real part of the file.
    //  While the unconsumed backlog is still over the cap the rewrite
    //  cannot bring the file under it, so skipping keeps the write
    //  amplification at 2x instead of copying the whole file for every
    //  byte a slow destination consumes.
    //  The skip is NOT unbounded, though: once the consumed prefix is at
    //  least half the file the copy pays for itself, so the file still
    //  shrinks.  That bounds the file at 2x the unconsumed backlog, which
    //  is the smallest it can ever be while that backlog is retained.
    const prefix = Math.min(target - this.base, size);
    const remaining = size - prefix;
    if (remaining >= this.maxJournalBytes && prefix * 2 < size) return false;
    await this.compactTo(target);
    return true;
  }

  /** Rewrite the journal file without the consumed prefix. */
  async compactTo(target) {
    await this.fileMutex(async () => {
      const size = await this.fileSize();
      const cut = Math.min(target - this.base, size);
      if (cut <= 0) return;
      const temporary = `${this.journalPath}.compact`;
      if (cut >= size) {
        await writeFile(temporary, "", { mode: FILE_MODE });
      } else {
        await this.copyRange(this.journalPath, temporary, cut, size);
      }
      //  The pending record is written BEFORE the swap, so a crash in
      //  between leaves enough information to settle the outcome.
      await this.writeBaseFile({ base: this.base, nextBase: target, pendingSize: size });
      await rename(temporary, this.journalPath);
      await chmod(this.journalPath, FILE_MODE);
      await this.writeBaseFile({ base: target, nextBase: target, pendingSize: 0 });
      this.base = target;
      if (this.handle) {
        await this.handle.close();
        this.handle = undefined;
      }
      this.handle = await open(this.journalPath, "a", FILE_MODE);
      await this.handle.chmod(FILE_MODE);
    });
  }

  /** Copy a byte range of one file into another file. */
  async copyRange(source, target, from, to) {
    const input = await open(source, fsConstants.O_RDONLY);
    const output = await open(target, "w", FILE_MODE);
    try {
      const buffer = Buffer.alloc(READ_CHUNK_BYTES);
      let position = from;
      while (position < to) {
        const want = Math.min(READ_CHUNK_BYTES, to - position);
        const { bytesRead } = await input.read(buffer, 0, want, position);
        if (bytesRead <= 0) break;
        await output.write(buffer.subarray(0, bytesRead), 0, bytesRead, position - from);
        position += bytesRead;
      }
      await output.sync();
    } finally {
      await output.close();
      await input.close();
    }
  }

  /**
   * Quarantine one event into the dead-letter file.
   *
   * The record carries the event id, the metric type, the destination and a
   * reason.  It carries NO content: no prompt, no response, no tool
   * argument.  The journal itself stays the only place content lives.
   */
  async quarantine(destination, event, { reason, status } = {}) {
    const key = normalizeDestination(destination);
    const record = {
      quarantinedAt: new Date().toISOString(),
      destination: key,
      eventId: typeof event?.eventId === "string" ? event.eventId : "",
      metricType: typeof event?.operation === "string" ? event.operation : "",
      provider: typeof event?.provider === "string" ? event.provider : "",
      status: typeof event?.status === "string" ? event.status : "",
      reason: typeof reason === "string" ? reason.slice(0, 200) : "",
      httpStatus: Number.isInteger(status) ? status : undefined,
    };
    const line = `${JSON.stringify(record)}\n`;
    const file = await open(this.deadLetterPath, "a", FILE_MODE);
    try {
      await file.write(line, null, "utf8");
      await file.sync();
    } finally {
      await file.close();
    }
    return record;
  }

  /** Close the journal handle. */
  async close() {
    if (this.handle) {
      await this.handle.close();
      this.handle = undefined;
    }
  }
}

// The Sentry sender.
//
// Sentry gets ONLY counts, durations, the model, the tool names and a
// status.  It never gets the prompt, the response, the tool arguments, the
// tool results, a file path, a project name, a session id or a raw error
// message.
//
// The scrubber in ./allowlist.mjs is the control.  Sentry's own default
// scrubbing does not protect `gen_ai.input.messages`,
// `gen_ai.output.messages`, `gen_ai.tool.call.arguments` or
// `gen_ai.tool.call.result`, and plain OTLP bypasses the SDK PII flags
// entirely, so the content is removed on this Mac before the packet
// leaves.
//
// Two envelopes go out: `/v1/traces` for the turn events and `/v1/logs` for
// the log events.  Sentry has no OTLP metrics path, so none is attempted.
//
// The endpoint is project-specific and region-specific, so it is read from
// the environment and never hardcoded.  The public key is not a secret, but
// it is still read from the environment.

import { gzipSync } from "node:zlib";
import { z } from "zod";

import { scrubInternalEvent } from "./allowlist.mjs";
import { NULL_LOGGER } from "./internal-event.mjs";
import { eventIdOf } from "./journal.mjs";

/**
 * Success ACKs are byte-bounded and retain only typed rejection counts.
 * Response messages, rejection bodies and headers are never persisted.
 */
const AckCount = z.union([z.number(), z.string().max(16).regex(/^(0|[1-9][0-9]*)$/).transform(Number)]).pipe(z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER));
export const MAX_SENTRY_ACK_BYTES = 64 * 1024;

async function readSuccessAck(response, logs, submitted) {
  let text = "";
  let reader;
  try {
    if (response.body === undefined) return { responseClass: "unreadable_ack" };
    if (response.body) {
      if (typeof response.body.getReader !== "function") return { responseClass: "unreadable_ack" };
      reader = response.body.getReader();
      const chunks = [];
      let bytes = 0;
      for (;;) {
        const next = await reader.read();
        if (next.done) break;
        bytes += next.value.byteLength;
        if (bytes > MAX_SENTRY_ACK_BYTES) {
          await reader.cancel().catch(() => {});
          return { responseClass: "oversized_ack" };
        }
        chunks.push(next.value);
      }
      text = new TextDecoder("utf-8", { fatal: true }).decode(Buffer.concat(chunks));
    }
  } catch { return { responseClass: "unreadable_ack" }; }
  finally { reader?.releaseLock(); }
  const contentType = response.headers?.get("content-type")?.split(";", 1)[0].trim().toLowerCase();
  const jsonType = !contentType || contentType === "application/json" || /^application\/[a-z0-9.+-]+\+json$/.test(contentType);
  const emptyProtobuf = !text.trim() && ["application/x-protobuf", "application/protobuf"].includes(contentType);
  if (!jsonType && !emptyProtobuf) return { responseClass: "unexpected_content_type" };
  if (!text.trim()) return { accepted: true };
  const camel = logs ? "rejectedLogRecords" : "rejectedSpans";
  const snake = logs ? "rejected_log_records" : "rejected_spans";
  const schema = z.strictObject({
    partialSuccess: z.strictObject({ [camel]: AckCount.optional(), errorMessage: z.string().optional() }).optional(),
    partial_success: z.strictObject({ [snake]: AckCount.optional(), error_message: z.string().optional() }).optional(),
  }).refine((ack) => !(ack.partialSuccess && ack.partial_success));
  let result;
  try { result = schema.safeParse(JSON.parse(text)); } catch { return { responseClass: "malformed_ack" }; }
  if (!result.success) return { responseClass: "malformed_ack" };
  const partial = result.data.partialSuccess ?? result.data.partial_success;
  const rejected = partial?.[camel] ?? partial?.[snake] ?? 0;
  if (rejected > submitted) return { responseClass: "malformed_ack" };
  return rejected > 0 ? { responseClass: "partial_success", rejectedCount: rejected } : { accepted: true };
}

/** The Sentry OTLP envelopes.  Sentry does not support OTLP metrics. */
export const SENTRY_TRACES_PATH = "/v1/traces";
export const SENTRY_LOGS_PATH = "/v1/logs";

/** Sentry accepts at most 100 log records per envelope. */
export const MAX_LOGS_PER_REQUEST = 100;

/** Sentry accepts at most 1000 spans per request. */
export const MAX_SPANS_PER_REQUEST = 1000;

/** Keep every request body well under 1 MB, far inside the 12 MiB cap. */
export const MAX_BODY_CHARS = 512 * 1024;

/** How many journal events one pass reads before it splits them by kind. */
export const DEFAULT_READ_LIMIT = 200;

const REQUEST_TIMEOUT_MS = 20_000;
const MAX_ATTEMPTS = 3;
const BASE_BACKOFF_MS = 1_000;

/** The service name Sentry sees. */
const SERVICE_NAME = "telemetry-hub";
const SERVICE_VERSION = "1";

function isPlainObject(value) {
  return !!value && typeof value === "object" && !Array.isArray(value);
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Classify an HTTP status.  Same policy as the UM sender: a validation
 * failure is a poison event, an auth or routing failure is the channel's
 * own problem, and 429/5xx is transient.
 */
export function classifyStatus(status) {
  if (status >= 200 && status < 300) return "ok";
  if (status === 429 || status >= 500) return "retry";
  if (status === 400 || status === 409 || status === 422) return "poison";
  return "channel";
}

function isoToNanos(iso) {
  const time = Date.parse(iso);
  if (!Number.isFinite(time)) return undefined;
  return String(BigInt(Math.round(time)) * 1_000_000n);
}

/** A 32 hex trace id and a 16 hex span id, derived from the event id. */
export function traceAndSpanIds(eventId) {
  const hex = typeof eventId === "string" ? eventId.replace(/[^0-9a-f]/gi, "").toLowerCase() : "";
  const traceId = (hex + "0".repeat(32)).slice(0, 32);
  const spanId = (hex + "0".repeat(16)).slice(0, 16);
  return { traceId, spanId };
}

/**
 * Build the OTLP traces envelope for a list of SCRUBBED events.
 *
 * The input is already scrubbed, so this function never sees a prompt or a
 * response and never has to decide whether one is safe.
 */
export function buildTracesEnvelope(events) {
  const spans = [];
  for (const event of events) {
    if (!isPlainObject(event)) continue;
    const { traceId, spanId } = traceAndSpanIds(event.eventId);
    const start = isoToNanos(event.ts);
    const durationMs = typeof event.durationMs === "number" ? event.durationMs : 0;
    const end = start ? String(BigInt(start) + BigInt(Math.max(0, Math.round(durationMs)) * 1_000_000)) : undefined;
    const span = {
      traceId,
      spanId,
      name: typeof event.name === "string" && event.name ? event.name : "chat",
      kind: 3,
      attributes: Array.isArray(event.attributes) ? event.attributes : [],
    };
    if (start) span.startTimeUnixNano = start;
    if (end) span.endTimeUnixNano = end;
    if (isPlainObject(event.status)) span.status = { code: event.status.code };
    spans.push(span);
  }
  return {
    resourceSpans: [
      {
        resource: {
          attributes: [
            { key: "service.name", value: { stringValue: SERVICE_NAME } },
            { key: "service.version", value: { stringValue: SERVICE_VERSION } },
          ],
        },
        scopeSpans: [{ scope: { name: SERVICE_NAME }, spans }],
      },
    ],
  };
}

/**
 * Build the OTLP logs envelope for a list of SCRUBBED events.
 *
 * The body was rebuilt by the scrubber from allowlisted fields, so it never
 * contains producer free text.
 */
export function buildLogsEnvelope(events) {
  const logRecords = [];
  for (const event of events) {
    if (!isPlainObject(event)) continue;
    const { traceId, spanId } = traceAndSpanIds(event.eventId);
    const record = {
      timeUnixNano: isoToNanos(event.ts) ?? String(Date.now() * 1_000_000),
      severityNumber: typeof event.severityNumber === "number" ? event.severityNumber : 9,
      body: isPlainObject(event.body) ? event.body : { stringValue: "" },
      traceId,
      spanId,
      attributes: Array.isArray(event.attributes) ? event.attributes : [],
    };
    logRecords.push(record);
  }
  return {
    resourceLogs: [
      {
        resource: {
          attributes: [
            { key: "service.name", value: { stringValue: SERVICE_NAME } },
            { key: "service.version", value: { stringValue: SERVICE_VERSION } },
          ],
        },
        scopeLogs: [{ scope: { name: SERVICE_NAME }, logRecords }],
      },
    ],
  };
}

/**
 * Split a list into chunks that respect both a count cap and a body size
 * cap.  The body cap is checked on the serialized envelope, so a batch of
 * very large attribute values is split before it reaches the 12 MiB cap.
 *
 * The size of ONE event is measured once and the running total is carried
 * along.  Re-serializing the whole candidate for every event made the pass
 * quadratic and could build hundreds of megabytes of discarded JSON.
 */
export function chunkBySize(events, build, { maxCount, maxChars }) {
  const chunks = [];
  let current = [];
  let currentChars = 0;
  //  The fixed part of the envelope is serialized once, and every event
  //  gets an allowance for the ids and the timestamps the envelope adds.
  const overhead = JSON.stringify(build([])).length;
  const perEventAllowance = 256;
  const limit = Math.max(1, maxChars - overhead);
  for (const event of events) {
    const eventChars = JSON.stringify(event ?? null).length + perEventAllowance;
    const candidateChars = currentChars + eventChars;
    if (current.length > 0 && (current.length + 1 > maxCount || candidateChars > limit)) {
      chunks.push(current);
      current = [event];
      currentChars = eventChars;
      continue;
    }
    current.push(event);
    currentChars = candidateChars;
  }
  if (current.length > 0) chunks.push(current);
  return chunks;
}

/**
 * Create the Sentry sender.
 *
 * @param {object} options
 * @param {import("./journal.mjs").Journal} options.journal
 */
export function createSentrySender({
  journal,
  endpoint = process.env.SENTRY_OTLP_ENDPOINT?.trim(),
  publicKey = process.env.SENTRY_PUBLIC_KEY?.trim(),
  readLimit = DEFAULT_READ_LIMIT,
  dryRun = false,
  logger = NULL_LOGGER,
  fetchImpl = globalThis.fetch,
  retryDelayMs = BASE_BACKOFF_MS,
} = {}) {
  if (!journal) throw new Error("The Sentry sender needs a journal");
  const destination = "sentry";
  const root = endpoint ? endpoint.replace(/\/+$/, "") : "";
  let inFlight = false;
  let blocked = false;
  let holdWarningSent = false;

  function warnHeld({ responseClass, heldEvents = 0, rejectedCount } = {}) {
    if (holdWarningSent) return;
    holdWarningSent = true;
    logger.warn("sentry delivery is held", { destination, responseClass: responseClass ?? "unresolved_intent", heldEvents, ...(rejectedCount === undefined ? {} : { rejectedCount }) });
  }

  async function post(path, envelope, submitted) {
    const json = JSON.stringify(envelope);
    const body = gzipSync(Buffer.from(json, "utf8"));
    let response;
    try {
      response = await fetchImpl(`${root}${path}`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "content-encoding": "gzip",
          "x-sentry-auth": `sentry sentry_key=${publicKey}`,
          "content-length": String(body.length),
        },
        body,
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
    } catch (error) {
      return { outcome: "retry", status: 0, errorName: error?.name ?? "Error" };
    }
    const outcome = classifyStatus(response.status);
    if (outcome === "ok") {
      const ack = await readSuccessAck(response, path === SENTRY_LOGS_PATH, submitted);
      return ack.accepted ? { outcome, status: response.status } : { outcome: "held", status: response.status, ...ack };
    }
    // Rejection bodies can echo producer content; only the HTTP class is needed.
    await response.body?.cancel?.().catch(() => {});
    return { outcome, status: response.status };
  }

  async function postWithRetry(path, envelope, submitted) {
    let last = { outcome: "retry", status: 0 };
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      last = await post(path, envelope, submitted);
      if (last.outcome !== "retry") return last;
      if (attempt < MAX_ATTEMPTS && retryDelayMs > 0) {
        await sleep(retryDelayMs * 2 ** (attempt - 1));
      }
    }
    return last;
  }

  /**
   * Deliver one group of events, isolating a single poisoned event.
   *
   * A poison response is answered for the whole envelope, so the group is
   * halved until one event is left; that event is quarantined and the rest
   * is delivered.
   */
  async function deliverGroup(events, path, build) {
    const delivered = [];
    const quarantined = [];

    const attempt = async (subset) => {
      let intent;
      let result;
      try {
        intent = await journal.prepareSentryRequest(path === SENTRY_LOGS_PATH ? "logs" : "traces", subset);
        result = await postWithRetry(path, build(intent.events), subset.length);
        if (result.outcome === "held") {
          blocked = true;
          warnHeld({ responseClass: result.responseClass, heldEvents: subset.length, rejectedCount: result.rejectedCount });
          await journal.holdSentryRequest(intent.batchDigest, { responseClass: result.responseClass, rejectedCount: result.rejectedCount, httpStatus: result.status });
          return { ...result, heldEvents: subset.length };
        }
        if (result.outcome === "ok") await journal.markSentBatch(destination, intent.eventIds);
        await journal.clearSentryRequest(intent.batchDigest);
      } catch (error) {
        blocked = true;
        throw error;
      }
      if (result.outcome === "ok") {
        delivered.push(...subset);
        return { outcome: "ok" };
      }
      if (result.outcome === "retry" || result.outcome === "channel") {
        return { outcome: result.outcome, status: result.status };
      }
      if (subset.length === 1) {
        quarantined.push(subset[0]);
        await journal.quarantine(destination, subset[0], {
          reason: "sentry rejected the event",
          status: result.status,
        });
        logger.warn("quarantined an event", {
          destination,
          eventId: subset[0]?.eventId,
          metricType: subset[0]?.operation,
          status: result.status,
        });
        return { outcome: "ok" };
      }
      const middle = Math.ceil(subset.length / 2);
      const left = await attempt(subset.slice(0, middle));
      if (left.outcome !== "ok") return left;
      const right = await attempt(subset.slice(middle));
      if (right.outcome !== "ok") return right;
      return { outcome: "ok" };
    };

    const result = await attempt(events);
    return { ...result, delivered, quarantined };
  }

  /** One pass over the Sentry destination. */
  async function runOnce() {
    //  A pass can outlive the delivery tick.  The guard keeps two passes
    //  from delivering the same events twice and from writing the same
    //  offset file at the same time.  The hub guards the whole pass as
    //  well; this one makes the sender safe on its own.
    if (inFlight) return { ok: true, delivered: 0, quarantined: 0, busy: true };
    inFlight = true;
    try {
      return await runOnceGuarded();
    } finally {
      inFlight = false;
    }
  }

  async function runOnceGuarded() {
    let request;
    try { request = await journal.readSentryRequest(); }
    catch { blocked = true; warnHeld({ responseClass: "invalid_request_state" }); }
    if (blocked || request) {
      warnHeld({ responseClass: request?.responseClass, heldEvents: request?.events.length, rejectedCount: request?.rejectedCount });
      return { ok: false, retry: false, held: true, delivered: 0, quarantined: 0, ...(request ? { heldEvents: request.events.length, responseClass: request.responseClass ?? "unresolved_intent", ...(request.rejectedCount === undefined ? {} : { rejectedCount: request.rejectedCount }) } : {}) };
    }
    const batch = await journal.readBatch(destination, readLimit);
    if (batch.events.length === 0) {
      return { ok: true, delivered: 0, quarantined: 0, empty: true };
    }

    // S1: the content fields are stripped before the scrubber runs, and the
    // scrubber drops them as well.  Two independent barriers.
    const scrubbed = batch.events
      .map((event) => scrubInternalEvent(event))
      .filter((event) => !!event);

    const spans = scrubbed.filter((event) => event.kind !== "log");
    const logs = scrubbed.filter((event) => event.kind === "log");

    if (dryRun) {
      logger.info("sentry dry run", {
        destination,
        events: batch.events.length,
        spans: spans.length,
        logs: logs.length,
        attributeKeys: [...new Set(scrubbed.flatMap((event) => event.attributes.map((a) => a.key)))].sort(),
      });
      return { ok: true, delivered: 0, quarantined: 0, dryRun: true };
    }

    if (!root || !publicKey) {
      logger.error("the sentry otlp endpoint or public key is not configured", { destination });
      return { ok: false, retry: false, delivered: 0, quarantined: 0 };
    }

    const deliveredIds = [];
    let quarantined = 0;

    const spanChunks = chunkBySize(spans, buildTracesEnvelope, {
      maxCount: MAX_SPANS_PER_REQUEST,
      maxChars: MAX_BODY_CHARS,
    });
    for (const chunk of spanChunks) {
      const outcome = await deliverGroup(chunk, SENTRY_TRACES_PATH, buildTracesEnvelope);
      if (outcome.outcome !== "ok") {
        //  Whatever was delivered before the failure stays delivered, so
        //  the next pass does not send it again.  That includes the events
        //  of the failed chunk that the isolation split delivered before
        //  the failure: they reached Sentry, so they must be marked.
        const partial = [...outcome.delivered, ...outcome.quarantined]
          .map((event) => eventIdOf(event))
          .filter((id) => typeof id === "string" && id);
        await journal.markSentBatch(destination, [...deliveredIds, ...partial]);
        logger.warn("sentry is not accepting the batch", {
          destination,
          path: SENTRY_TRACES_PATH,
          status: outcome.status,
          outcome: outcome.outcome,
        });
        return { ok: false, retry: outcome.outcome === "retry", delivered: deliveredIds.length + outcome.delivered.length, quarantined: quarantined + outcome.quarantined.length, ...(outcome.outcome === "held" ? { held: true, heldEvents: outcome.heldEvents, responseClass: outcome.responseClass, ...(outcome.rejectedCount === undefined ? {} : { rejectedCount: outcome.rejectedCount }) } : {}) };
      }
      const ids = [...outcome.delivered, ...outcome.quarantined]
        .map((event) => event.eventId)
        .filter((id) => typeof id === "string" && id);
      quarantined += outcome.quarantined.length;
      await journal.markSentBatch(destination, ids);
      deliveredIds.push(...outcome.delivered.map((event) => event.eventId));
    }

    const logChunks = chunkBySize(logs, buildLogsEnvelope, {
      maxCount: MAX_LOGS_PER_REQUEST,
      maxChars: MAX_BODY_CHARS,
    });
    for (const chunk of logChunks) {
      const outcome = await deliverGroup(chunk, SENTRY_LOGS_PATH, buildLogsEnvelope);
      if (outcome.outcome !== "ok") {
        //  The same rule as the span chunks: the events of the failed
        //  chunk that were delivered before the failure stay delivered.
        const partial = [...outcome.delivered, ...outcome.quarantined]
          .map((event) => eventIdOf(event))
          .filter((id) => typeof id === "string" && id);
        await journal.markSentBatch(destination, [...deliveredIds, ...partial]);
        logger.warn("sentry is not accepting the batch", {
          destination,
          path: SENTRY_LOGS_PATH,
          status: outcome.status,
          outcome: outcome.outcome,
        });
        return { ok: false, retry: outcome.outcome === "retry", delivered: deliveredIds.length + outcome.delivered.length, quarantined: quarantined + outcome.quarantined.length, ...(outcome.outcome === "held" ? { held: true, heldEvents: outcome.heldEvents, responseClass: outcome.responseClass, ...(outcome.rejectedCount === undefined ? {} : { rejectedCount: outcome.rejectedCount }) } : {}) };
      }
      const ids = [...outcome.delivered, ...outcome.quarantined]
        .map((event) => event.eventId)
        .filter((id) => typeof id === "string" && id);
      quarantined += outcome.quarantined.length;
      await journal.markSentBatch(destination, ids);
      deliveredIds.push(...outcome.delivered.map((event) => event.eventId));
    }

    await journal.setOffset(destination, batch.endOffset);
    return {
      ok: true,
      delivered: deliveredIds.length,
      quarantined,
    };
  }

  return {
    destinations: [destination],
    runOnce,
  };
}

